    /* we update the pool header of the next block */
    *next = POOL_FREE_HEADER(Wosize_hp(p) - 1);
    /* also copy the next_obj pointer from p */
    CAMLassert(p[1] == 0 || POOL_BLOCK_FREE_HP(p[1]));
    next[1] = p[1];
